"""Minimal n-dimensional numeric tensor (CPU, standard library only)."""

from __future__ import annotations

import math


def _normalize(data):
    """Validate *data* and return ``(shape, deep-copied nested lists)``."""
    if isinstance(data, bool):
        raise ValueError("Tensor data must be numeric; booleans are not allowed")
    if isinstance(data, (int, float)):
        return [], data
    if isinstance(data, (list, tuple)):
        if len(data) == 0:
            raise ValueError("Tensor data must not be empty")
        shape = None
        items = []
        for item in data:
            sub_shape, value = _normalize(item)
            if shape is None:
                shape = sub_shape
            elif sub_shape != shape:
                raise ValueError(
                    "Tensor data is ragged: nested sequences must all have the same shape"
                )
            items.append(value)
        return [len(items)] + shape, items
    raise ValueError(
        "Tensor data must be a number or a nested sequence of numbers, "
        f"got {type(data).__name__}"
    )


def _deep_copy(value):
    if isinstance(value, list):
        return [_deep_copy(item) for item in value]
    return value


class Tensor:
    """An n-dimensional container of numbers with a ``grad`` slot.

    ``grad`` starts as ``None``; layers accumulate gradients onto it and
    ``Sequential.zero_grad()`` resets it to an all-zeros tensor.
    """

    __slots__ = ("_data", "_shape", "grad")

    def __init__(self, data):
        self._shape, self._data = _normalize(data)
        self.grad = None

    @property
    def shape(self):
        return list(self._shape)

    def tolist(self):
        return _deep_copy(self._data)

    def __repr__(self):
        return f"Tensor(shape={self._shape}, data={self._data!r})"

    # -- internal engine hooks (not part of the public README surface) ------

    def _values(self):
        """Return the raw nested storage (not a copy)."""
        return self._data

    def _set_values(self, values):
        """Replace the raw nested storage with an already-validated tree."""
        self._data = values

    def _scaled_subtract_(self, other, scale):
        """Subtract *scale* times *other* in place, element by element.

        The arithmetic happens in a fixed left-to-right order so the
        result is identical to an uninterrupted run.
        """
        self._data = _scaled_subtract(self._data, other._data, float(scale))

    def _all_finite(self):
        return _all_finite(self._data)


def _scaled_subtract(a, b, scale):
    if isinstance(a, list):
        return [_scaled_subtract(x, y, scale) for x, y in zip(a, b)]
    return a - scale * b


def _all_finite(value):
    if isinstance(value, list):
        return all(_all_finite(item) for item in value)
    return isinstance(value, int) or (
        isinstance(value, float) and math.isfinite(value)
    )

"""Sequential container: chains caller-provided layers in registration order."""

from __future__ import annotations

from . import checkpoint as _checkpoint
from .tensor import Tensor

_REQUIRED_CAPABILITIES = ("forward", "backward", "parameters")


def _zeros(shape):
    if not shape:
        return 0.0
    return [_zeros(shape[1:]) for _ in range(shape[0])]


def _layer_kind(module):
    kind = getattr(module, "checkpoint_kind", None)
    if kind is None:
        kind = type(module).__name__
    if not isinstance(kind, str) or not kind:
        raise ValueError("layer checkpoint_kind must be a non-empty string")
    return kind


class Sequential:
    """Chains caller-provided layers in registration order.

    Each layer must provide ``forward``, ``backward`` and ``parameters``.
    ``forward(batch, hidden=None)`` runs the batch through every layer in
    order; each layer consumes the previous layer's output plus its own
    hidden-state slot (``None`` when no hidden state is supplied, meaning
    the layer restarts from zeros) and returns an ``(output, hidden_slot)``
    pair. The slots stack in registration order into the chain's hidden
    state.

    The engine keeps no gradient history across ``forward`` calls: hidden
    states carry values only, so a backward pass on a later segment can
    never add gradients to an earlier one. ``backward(loss)`` starts from
    the caller-computed scalar loss and walks the layers in reverse order,
    each layer passing the upstream gradient back and accumulating
    parameter gradients on its own tensors.

    Besides the forward/backward cycle the container offers:

    * ``update(learning_rate)`` -- one in-place gradient step
      ``theta <- theta - lr * grad`` on every parameter; gradients are
      not cleared (``zero_grad`` still does that).
    * ``save(target)`` / ``load(source)`` -- atomic, versioned snapshots of
      parameters, accumulated gradients and slice-boundary hidden state,
      to a filesystem path or to an in-memory ``bytearray``.
    """

    def __init__(self, modules):
        if isinstance(modules, (str, bytes)):
            raise ValueError("Sequential expects a non-empty sequence of layers")
        try:
            modules = list(modules)
        except TypeError:
            raise ValueError(
                "Sequential expects a non-empty sequence of layers"
            ) from None
        if len(modules) == 0:
            raise ValueError("Sequential requires at least one layer")
        for index, module in enumerate(modules):
            missing = [
                name
                for name in _REQUIRED_CAPABILITIES
                if not callable(getattr(module, name, None))
            ]
            if missing:
                raise ValueError(
                    f"layer at index {index} is missing required "
                    f"capabilit{'ies' if len(missing) > 1 else 'y'}: "
                    + ", ".join(missing)
                )
        self._modules = modules
        self._pending_backward = False
        self._hidden_shapes = None
        self._last_output = None
        self._last_hidden = None

    def forward(self, batch, hidden=None):
        if not isinstance(batch, Tensor):
            raise ValueError("batch must be a Tensor")
        batch_shape = batch.shape
        if len(batch_shape) == 0 or batch_shape[0] <= 0:
            raise ValueError("batch must be non-empty")
        slots = self._prepare_hidden(hidden)
        x = batch
        new_hidden = []
        for module, slot in zip(self._modules, slots):
            result = module.forward(x, slot)
            try:
                x, slot_out = result
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    "each layer's forward must return an (output, hidden) pair"
                ) from exc
            if not isinstance(x, Tensor) or not isinstance(slot_out, Tensor):
                raise ValueError("each layer's forward must return (Tensor, Tensor)")
            new_hidden.append(slot_out)
        self._hidden_shapes = [slot.shape for slot in new_hidden]
        self._last_output = x
        self._last_hidden = new_hidden
        self._pending_backward = True
        return x, new_hidden

    def backward(self, loss):
        if not self._pending_backward:
            raise RuntimeError(
                "backward() requires a preceding forward() and may only be "
                "called once per forward()"
            )
        upstream = self._parse_loss(loss)
        # Snapshot gradients first: if any layer raises mid-pass, roll the
        # partial accumulation back so the state is exactly as if backward
        # had never run and the caller may retry the same forward's backward
        # (that retry is not a second backward pass).
        grad_snapshot = [
            None if param.grad is None else param.grad.tolist()
            for param in self.parameters()
        ]
        try:
            for module in reversed(self._modules):
                upstream = module.backward(upstream)
        except BaseException:
            for param, saved in zip(self.parameters(), grad_snapshot):
                param.grad = None if saved is None else Tensor(saved)
            raise
        self._pending_backward = False

    def _parse_loss(self, loss):
        if isinstance(loss, bool):
            raise ValueError("loss must be numeric, not a boolean")
        if isinstance(loss, (int, float, Tensor)):
            return loss
        if isinstance(loss, tuple):
            if len(loss) != 2:
                raise ValueError(
                    "tuple loss must be (output, upstream): exactly two elements"
                )
            output, upstream = loss
            if output is not self._last_output:
                raise ValueError(
                    "tuple loss must carry the Tensor returned by the "
                    "preceding forward() call"
                )
            if isinstance(upstream, bool) or not isinstance(
                upstream, (int, float, Tensor)
            ):
                raise ValueError(
                    "tuple loss upstream must be a number or a Tensor"
                )
            return upstream
        raise ValueError(
            "loss must be a scalar, a Tensor, or an (output, upstream) tuple"
        )

    def zero_grad(self):
        for param in self.parameters():
            param.grad = Tensor(_zeros(param.shape))

    def parameters(self):
        params = []
        for module in self._modules:
            params.extend(module.parameters())
        return params

    def update(self, learning_rate):
        """Perform one in-place step ``theta <- theta - learning_rate * grad``.

        Every parameter is updated in fixed registration order using its
        accumulated gradient; parameters without a gradient slot are left
        untouched (their gradient is implicitly zero). Gradients are not
        cleared -- ``zero_grad`` remains the only way to reset them.
        """
        if isinstance(learning_rate, bool) or not isinstance(
            learning_rate, (int, float)
        ):
            raise ValueError("learning rate must be a number")
        if learning_rate != learning_rate or learning_rate in (
            float("inf"),
            float("-inf"),
        ):
            raise ValueError("learning rate must be finite")
        for param in self.parameters():
            if param.grad is not None:
                param._scaled_subtract_(param.grad, learning_rate)

    # -- checkpoints --------------------------------------------------------

    def save(self, target):
        """Fix the full training state into *target*.

        *target* is either a filesystem path (``str``/``os.PathLike``) or a
        ``bytearray`` used as an in-memory buffer. The snapshot records
        every parameter tensor, every accumulated gradient (zeros for
        parameters that have never received one), the current
        slice-boundary hidden state, the layer order with per-layer
        parameter shapes and the format version.

        A snapshot may only be taken at a segment boundary -- i.e. when no
        backward pass is pending -- because a forward's intermediate
        activations live inside the caller's layers and cannot be fixed by
        the engine. Saving mutates no existing state and repeated saves
        produce identical bytes.
        """
        if self._pending_backward:
            raise RuntimeError(
                "save() requires a completed segment: call backward() for the "
                "pending forward() first"
            )
        params = self.parameters()
        document = {
            "params": [
                {"s": param.shape, "v": param.tolist()} for param in params
            ],
            "grads": [
                {
                    "s": param.shape,
                    "v": param.grad.tolist()
                    if param.grad is not None
                    else _zeros(param.shape),
                }
                for param in params
            ],
            "hidden": None
            if self._last_hidden is None
            else [
                {"s": slot.shape, "v": slot.tolist()} for slot in self._last_hidden
            ],
            "layers": [
                {
                    "kind": _layer_kind(module),
                    "shapes": [param.shape for param in module.parameters()],
                }
                for module in self._modules
            ],
            "pending": False,
        }
        return _checkpoint.save_bytes(document, target)

    def load(self, source):
        """Restore state previously written by ``save``.

        *source* is a filesystem path or a bytes-like buffer. The whole
        checkpoint is validated before anything is applied: the format
        version, every tensor shape and the layer order (count, kinds and
        per-layer parameter shapes) must match this container exactly. A
        missing path raises ``FileNotFoundError``; any structural problem
        rejects the entire checkpoint with ``ValueError`` and leaves the
        container untouched.

        On success returns the restored slice-boundary hidden-state list
        (one tensor per layer), or ``None`` when the checkpoint fixed the
        start-of-training state. Feed it back into the next
        ``forward(batch, hidden)`` to continue the sequence.
        """
        document = _checkpoint.load_bytes(source)
        self._validate_against_model(document)

        params = self.parameters()
        for param, entry in zip(params, document["params"]):
            param._set_values(_rebuild_tree(entry["v"], entry["s"]))
        for param, entry in zip(params, document["grads"]):
            param.grad = Tensor(_rebuild_tree(entry["v"], entry["s"]))
        if document["hidden"] is None:
            self._last_hidden = None
            self._hidden_shapes = None
            restored_hidden = None
        else:
            slots = [
                Tensor(_rebuild_tree(entry["v"], entry["s"]))
                for entry in document["hidden"]
            ]
            self._last_hidden = slots
            self._hidden_shapes = [slot.shape for slot in slots]
            restored_hidden = [Tensor(slot.tolist()) for slot in slots]
        self._last_output = None
        self._pending_backward = False
        return restored_hidden

    def _validate_against_model(self, document):
        if not isinstance(document, dict):
            raise ValueError("checkpoint is not a valid state document")
        params = self.parameters()
        saved_params = document.get("params")
        saved_grads = document.get("grads")
        if (
            not isinstance(saved_params, list)
            or not isinstance(saved_grads, list)
            or len(saved_params) != len(params)
            or len(saved_grads) != len(params)
        ):
            raise ValueError(
                "checkpoint parameter count does not match the current model"
            )
        for index, (param, p_entry, g_entry) in enumerate(
            zip(params, saved_params, saved_grads)
        ):
            if not isinstance(p_entry, dict) or not isinstance(g_entry, dict):
                raise ValueError(f"checkpoint parameter {index} is malformed")
            if p_entry.get("s") != param.shape or g_entry.get("s") != param.shape:
                raise ValueError(
                    f"checkpoint parameter {index} shape does not match the "
                    f"current model"
                )

        saved_layers = document.get("layers")
        if not isinstance(saved_layers, list) or len(saved_layers) != len(
            self._modules
        ):
            raise ValueError(
                "checkpoint layer count does not match the current model"
            )
        offset = 0
        for index, (module, saved) in enumerate(zip(self._modules, saved_layers)):
            if not isinstance(saved, dict):
                raise ValueError(f"checkpoint layer {index} is malformed")
            if saved.get("kind") != _layer_kind(module):
                raise ValueError(
                    f"checkpoint layer {index} kind {saved.get('kind')!r} does "
                    f"not match the current model"
                )
            current_shapes = [p.shape for p in module.parameters()]
            if saved.get("shapes") != current_shapes:
                raise ValueError(
                    f"checkpoint layer {index} parameter shapes do not match "
                    f"the current model"
                )
            offset += len(current_shapes)
        if offset != len(params):
            raise ValueError("checkpoint layer order does not match parameters")

        saved_hidden = document.get("hidden")
        if saved_hidden is not None:
            if not isinstance(saved_hidden, list) or len(saved_hidden) != len(
                self._modules
            ):
                raise ValueError(
                    "checkpoint hidden slot count does not match the current model"
                )
            for index, entry in enumerate(saved_hidden):
                if not isinstance(entry, dict) or "s" not in entry:
                    raise ValueError(f"checkpoint hidden slot {index} is malformed")
                if self._hidden_shapes is not None and (
                    entry["s"] != self._hidden_shapes[index]
                ):
                    raise ValueError(
                        f"checkpoint hidden slot {index} shape does not match "
                        f"the current model"
                    )

        if document.get("pending") is not False:
            raise ValueError("checkpoint pending flag has an unexpected value")

    def _prepare_hidden(self, hidden):
        count = len(self._modules)
        if hidden is None:
            return [None] * count
        if not isinstance(hidden, (list, tuple)) or len(hidden) != count:
            raise ValueError(
                f"hidden must be a list of {count} tensors (one slot per layer)"
            )
        slots = list(hidden)
        for index, slot in enumerate(slots):
            if slot is None:
                continue
            if not isinstance(slot, Tensor):
                raise ValueError(f"hidden slot {index} must be a Tensor")
            expected = self._hidden_shapes[index] if self._hidden_shapes else None
            if expected is not None and slot.shape != expected:
                raise ValueError(
                    f"hidden slot {index} has shape {slot.shape}, expected {expected}"
                )
        return slots


def _rebuild_tree(value, shape):
    """Validate decoded leaves against *shape* and return a fresh nested tree."""
    if shape:
        if not isinstance(value, list) or len(value) != shape[0]:
            raise ValueError("checkpoint tensor values do not match their shape")
        return [_rebuild_tree(item, shape[1:]) for item in value]
    if isinstance(value, (list, bool)) or not isinstance(value, (int, float)):
        raise ValueError("checkpoint tensor values do not match their shape")
    return value

"""Checkpoint container: fixed binary snapshots for Sequential state.

A checkpoint fixes, in one self-describing document:

* every parameter tensor,
* every accumulated gradient (zeros when a parameter has none yet),
* the slice-boundary hidden state of the latest completed segment,
* the layer order and per-layer parameter shapes,
* the format version and the engine's pending-backward flag.

Wire format (all integers little-endian)::

    magic        8 bytes  b"SEQECKP1"
    version      uint32   format version
    header_len   uint64   length of the JSON header in bytes
    header       header_len bytes of UTF-8 JSON (shapes, layer order, flags)
    payload      one leaf per tensor element, each a 1-byte tag
                 ("i" | "f") followed by int64 or float64
    end_magic    12 bytes b"SEQECKP1END"
    leaf_count   uint64   number of encoded leaves
    payload_crc  uint32   CRC-32 of the header bytes followed by the payload

Float leaves are emitted as raw IEEE-754 bytes, so values (including the
sign of negative zero) round-trip bit for bit.  Non-finite floats and
integers that do not fit in int64 are refused up front.

Loading validates the whole document before anything is handed back:
truncation, corruption, a version mismatch or any structural problem
rejects the entire checkpoint with ValueError; nothing is silently filled
in.
"""

from __future__ import annotations

import json
import math
import os
import struct
import tempfile
import zlib

MAGIC = b"SEQECKP1"
END_MAGIC = b"SEQECKP1END"
FORMAT_VERSION = 1

_TAG_INT = ord("i")
_TAG_FLOAT = ord("f")

_INT64_MIN = -(2**63)
_INT64_MAX = 2**63 - 1

_TMP_PREFIX = ".seqckp.tmp-"


class CheckpointError(ValueError):
    """A checkpoint is truncated, corrupt, or structurally invalid."""


# ---------------------------------------------------------------------------
# Shape / tree helpers
# ---------------------------------------------------------------------------


def _check_shape(shape):
    if not isinstance(shape, list):
        raise CheckpointError("tensor shape must be a list of ints")
    for dim in shape:
        if isinstance(dim, bool) or not isinstance(dim, int) or dim <= 0:
            raise CheckpointError("tensor shape dimensions must be positive ints")

def _shape_matches(tree, shape):
    node = tree
    for dim in shape:
        if not isinstance(node, list) or len(node) != dim:
            return False
        node = node[0]
    return not isinstance(node, list)


def _shape_size(shape):
    size = 1
    for dim in shape:
        size *= dim
    return size


def _check_leaf(value):
    if isinstance(value, bool):
        raise CheckpointError("checkpoint values must be numbers, not booleans")
    if isinstance(value, int):
        if not _INT64_MIN <= value <= _INT64_MAX:
            raise CheckpointError(
                "checkpoint contains an integer too large to represent (int64)"
            )
        return _TAG_INT
    if isinstance(value, float):
        if not math.isfinite(value):
            raise CheckpointError("checkpoint contains a non-finite floating value")
        return _TAG_FLOAT
    raise CheckpointError(
        f"checkpoint values must be numbers, got {type(value).__name__}"
    )


# ---------------------------------------------------------------------------
# Freezing: snapshot document -> (JSON header, binary payload chunks)
# ---------------------------------------------------------------------------


def _freeze_tree(tree, shape, payload):
    if shape:
        if not isinstance(tree, list) or len(tree) != shape[0]:
            raise CheckpointError("tensor tree does not match its declared shape")
        for item in tree:
            _freeze_tree(item, shape[1:], payload)
    else:
        if isinstance(tree, list):
            raise CheckpointError("tensor tree does not match its declared shape")
        tag = _check_leaf(tree)
        payload.append(
            struct.pack("<bq", _TAG_INT, tree)
            if tag == _TAG_INT
            else struct.pack("<bd", _TAG_FLOAT, tree)
        )


def _freeze_entry(entry, payload):
    if not isinstance(entry, dict) or set(entry) != {"s", "v"}:
        raise CheckpointError("tensor entry must be an object with 's' and 'v'")
    shape = entry["s"]
    _check_shape(shape)
    tree = entry["v"]
    if not _shape_matches(tree, shape):
        raise CheckpointError("tensor tree does not match its declared shape")
    _freeze_tree(tree, shape, payload)
    return list(shape)


def _freeze_layer(layer):
    if not isinstance(layer, dict) or set(layer) != {"kind", "shapes"}:
        raise CheckpointError("layer descriptor must be an object with kind/shapes")
    kind = layer["kind"]
    if not isinstance(kind, str) or not kind:
        raise CheckpointError("layer kind must be a non-empty string")
    shapes = layer["shapes"]
    if not isinstance(shapes, list):
        raise CheckpointError("layer parameter shapes must be a list")
    for shape in shapes:
        _check_shape(shape)
    return {"kind": kind, "shapes": [list(shape) for shape in shapes]}


def _freeze(document):
    if not isinstance(document, dict):
        raise CheckpointError("checkpoint document must be an object")
    payload = []
    header = {"v": FORMAT_VERSION}

    entries = document.get("params")
    if not isinstance(entries, list):
        raise CheckpointError("checkpoint must record a parameter tensor list")
    header["params"] = [_freeze_entry(entry, payload) for entry in entries]

    grads = document.get("grads")
    if not isinstance(grads, list) or len(grads) != len(entries):
        raise CheckpointError("checkpoint must record one gradient slot per parameter")
    header["grads"] = [_freeze_entry(entry, payload) for entry in grads]

    hidden = document.get("hidden")
    if hidden is None:
        header["hidden"] = None
    else:
        if not isinstance(hidden, list) or not hidden:
            raise CheckpointError("hidden state must be a non-empty list or null")
        header["hidden"] = [_freeze_entry(entry, payload) for entry in hidden]

    layers = document.get("layers")
    if not isinstance(layers, list) or not layers:
        raise CheckpointError("checkpoint must record the layer order")
    header["layers"] = [_freeze_layer(layer) for layer in layers]
    if sum(len(layer["shapes"]) for layer in header["layers"]) != len(entries):
        raise CheckpointError("layer parameter counts do not match the parameter list")

    pending = document.get("pending")
    if not isinstance(pending, bool):
        raise CheckpointError("pending flag must be a boolean")
    header["pending"] = pending
    return header, payload


def build_bytes(document):
    """Serialize a snapshot document to the fixed binary representation."""
    header, payload = _freeze(document)
    header_bytes = json.dumps(
        header, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")

    body = bytearray()
    body += MAGIC
    body += struct.pack("<I", FORMAT_VERSION)
    body += struct.pack("<Q", len(header_bytes))
    body += header_bytes
    crc = zlib.crc32(header_bytes)
    leaf_count = 0
    for chunk in payload:
        body += chunk
        crc = zlib.crc32(chunk, crc)
        leaf_count += 1
    body += END_MAGIC
    body += struct.pack("<Q", leaf_count)
    body += struct.pack("<I", crc & 0xFFFFFFFF)
    return bytes(body)


# ---------------------------------------------------------------------------
# Parsing: raw bytes -> validated snapshot document
# ---------------------------------------------------------------------------


def parse_bytes(raw):
    """Validate and decode a checkpoint; return the snapshot document."""
    if not isinstance(raw, (bytes, bytearray, memoryview)):
        raise CheckpointError("checkpoint must be bytes")
    data = bytes(raw)

    prefix_len = len(MAGIC) + 4 + 8
    if len(data) < prefix_len:
        raise CheckpointError("checkpoint is truncated while reading its header")
    if data[: len(MAGIC)] != MAGIC:
        raise CheckpointError("not a sequence-engine checkpoint (bad magic)")
    (version,) = struct.unpack("<I", data[len(MAGIC) : len(MAGIC) + 4])
    if version != FORMAT_VERSION:
        raise CheckpointError(
            f"unsupported checkpoint version {version}; expected {FORMAT_VERSION}"
        )
    (header_len,) = struct.unpack(
        "<Q", data[len(MAGIC) + 4 : len(MAGIC) + 4 + 8]
    )
    if header_len <= 0:
        raise CheckpointError("checkpoint header length is invalid")

    # The fixed trailer is always the last 24 bytes; locate it via end_magic
    # so a torn write (missing/partial trailer) cannot be mistaken for data.
    trailer_pos = data.rfind(END_MAGIC)
    if trailer_pos < 0 or len(data) - trailer_pos != len(END_MAGIC) + 8 + 4:
        raise CheckpointError("checkpoint trailer is missing or the file is torn")
    header_start = prefix_len
    payload_end = trailer_pos
    if header_len > payload_end - header_start:
        raise CheckpointError("checkpoint header overruns the payload area")
    header_bytes = data[header_start : header_start + header_len]

    (leaf_count, stored_crc) = struct.unpack(
        "<QI", data[trailer_pos + len(END_MAGIC) :]
    )
    # CRC covers exactly the header followed by the payload.
    actual_crc = zlib.crc32(data[header_start:payload_end])
    if actual_crc != stored_crc:
        raise CheckpointError("checkpoint CRC mismatch: the file is corrupt or torn")

    try:
        header = json.loads(header_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CheckpointError(f"checkpoint header is invalid: {exc}") from exc
    if not isinstance(header, dict):
        raise CheckpointError("checkpoint header must be a JSON object")
    if header.get("v") != FORMAT_VERSION:
        raise CheckpointError("checkpoint header version does not match")

    _parse_header(header)
    total_leaves = sum(
        _shape_size(shape)
        for group in (header["params"], header["grads"])
        for shape in group
    )
    if header["hidden"] is not None:
        total_leaves += sum(_shape_size(shape) for shape in header["hidden"])
    if total_leaves != leaf_count:
        raise CheckpointError("checkpoint leaf count does not match the header")

    payload = data[header_start + header_len : payload_end]
    if len(payload) != leaf_count * 9:
        raise CheckpointError("checkpoint payload has the wrong size")

    reader = _LeafReader(payload)
    params = [{"s": shape, "v": reader.tree(shape)} for shape in header["params"]]
    grads = [{"s": shape, "v": reader.tree(shape)} for shape in header["grads"]]
    hidden = (
        None
        if header["hidden"] is None
        else [{"s": shape, "v": reader.tree(shape)} for shape in header["hidden"]]
    )
    if reader.remaining() != 0:
        raise CheckpointError("checkpoint payload has trailing bytes")
    return {
        "params": params,
        "grads": grads,
        "hidden": hidden,
        "layers": header["layers"],
        "pending": header["pending"],
    }


def _parse_header(header):
    for key in ("params", "grads", "hidden", "layers", "pending"):
        if key not in header:
            raise CheckpointError(f"checkpoint header is missing field {key!r}")
    params = _parse_shape_list(header["params"], "params", allow_empty=True)
    grads = _parse_shape_list(header["grads"], "grads", allow_empty=True)
    if len(params) != len(grads) or params != grads:
        raise CheckpointError("parameter and gradient shape lists must match")
    if header["hidden"] is not None:
        hidden = _parse_shape_list(header["hidden"], "hidden")
    else:
        hidden = None
    layers = header["layers"]
    if not isinstance(layers, list) or not layers:
        raise CheckpointError("layer order must be a non-empty list")
    layer_shapes = []
    for index, layer in enumerate(layers):
        if not isinstance(layer, dict) or set(layer) != {"kind", "shapes"}:
            raise CheckpointError(f"layer {index} descriptor must have kind/shapes")
        if not isinstance(layer["kind"], str) or not layer["kind"]:
            raise CheckpointError(f"layer {index} kind must be a non-empty string")
        shapes = _parse_shape_list(
            layer["shapes"], f"layer {index} shapes", allow_empty=True
        )
        layer_shapes.extend(shapes)
    if layer_shapes != params:
        raise CheckpointError(
            "layer order/parameter shapes do not match the parameter tensor list"
        )
    if not isinstance(header["pending"], bool):
        raise CheckpointError("pending flag must be a boolean")
    return params


def _parse_shape_list(value, what, allow_empty=False):
    if not isinstance(value, list) or (not value and not allow_empty):
        raise CheckpointError(f"{what} must be a list of shapes")
    shapes = []
    for shape in value:
        _check_shape(shape)
        shapes.append(list(shape))
    return shapes


class _LeafReader:
    def __init__(self, payload):
        self._payload = payload
        self._pos = 0

    def _leaf(self):
        tag = self._payload[self._pos]
        chunk = self._payload[self._pos + 1 : self._pos + 9]
        self._pos += 9
        if tag == _TAG_INT:
            return struct.unpack("<q", chunk)[0]
        if tag == _TAG_FLOAT:
            return struct.unpack("<d", chunk)[0]
        raise CheckpointError(f"unknown leaf tag {tag!r} in payload")

    def tree(self, shape):
        if not shape:
            return self._leaf()
        return [self.tree(shape[1:]) for _ in range(shape[0])]

    def remaining(self):
        return (len(self._payload) - self._pos) // 9


# ---------------------------------------------------------------------------
# Atomic file / memory IO
# ---------------------------------------------------------------------------


def save_bytes(document, target):
    """Write *document* to a path (str/os.PathLike) or a bytearray target.

    File writes go through a temporary file in the destination directory
    and are atomically renamed into place, overwriting any existing file
    without leaving a backup.  A torn temporary file is never renamed, so
    a crashed process can never leave a half-written checkpoint at the
    final path.
    """
    raw = build_bytes(document)
    if isinstance(target, bytearray):
        target.clear()
        target.extend(raw)
        return None
    if isinstance(target, (str, os.PathLike)):
        path = os.fspath(target)
        directory = os.path.dirname(os.path.abspath(path))
        fd, tmp_path = tempfile.mkstemp(prefix=_TMP_PREFIX, dir=directory)
        committed = False
        try:
            with os.fdopen(fd, "wb") as fh:
                fh.write(raw)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, path)
            committed = True
            _fsync_directory(directory)
        except BaseException:
            if not committed:
                try:
                    os.unlink(tmp_path)
                except FileNotFoundError:
                    pass
            raise
        return None
    raise TypeError("save target must be a path or bytearray")


def _fsync_directory(directory):
    """Best-effort durability for the rename; harmless where unsupported."""
    if not hasattr(os, "O_RDONLY") or not hasattr(os, "fsync"):
        return
    try:
        dir_fd = os.open(directory, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)


def load_bytes(source):
    """Read and validate a checkpoint from a path or from bytes/bytearray."""
    if isinstance(source, (str, os.PathLike)):
        with open(os.fspath(source), "rb") as fh:
            raw = fh.read()
        return parse_bytes(raw)
    if isinstance(source, (bytes, bytearray, memoryview)):
        return parse_bytes(source)
    raise TypeError("load source must be a path or bytes")

"""Entry point: python3 -m sequence_engine --selftest"""

from __future__ import annotations

