def _layer_digest(piece):
    """Content digest of one layer piece (its leaf bytes and structure)."""
    header = {
        "kind": piece["kind"],
        "shapes": piece["shapes"],
    }
    h = _FNV_OFFSET
    header_bytes = json.dumps(
        header, ensure_ascii=False, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    h = _fnv64_continue(h, header_bytes)
    for group in (piece["params"], piece["grads"]):
        for entry in group:
            shape = entry["s"]
            shape_bytes = json.dumps(shape, separators=(",", ":")).encode("utf-8")
            h = _fnv64_continue(h, shape_bytes)
            for leaf in _iter_leaves(entry["v"], shape):
                h = _fnv64_continue(h, _pack_leaf(leaf))
    return h & _FNV_MASK


def _fnv64(chunk):
    h = _FNV_OFFSET
    for byte in chunk:
        h ^= byte
        h = (h * _FNV_PRIME) & _FNV_MASK
    return h

