def _chain_lock(directory):
    """Acquire an exclusive advisory lock (plus an open file) for the chain."""
    lock_path = os.path.join(directory, ".seqckp.lock")
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o644)
    try:
        if hasattr(__import__("fcntl"), "flock"):
            import fcntl

            fcntl.flock(fd, fcntl.LOCK_EX)
    except BaseException:
        os.close(fd)
        raise
    return fd


